// Filter to only return queued/pending calls
const allRows = $input.all();

// Filter for queued status only
const queuedCalls = allRows.filter(item => {
  const status = (item.json.status || '').toLowerCase();
  return status === 'queued' || status === 'pending' || status === 'scheduled';
});

// Map to the expected format for the dashboard
const formattedCalls = queuedCalls.map(item => {
  const row = item.json;

  // Build lead name
  const firstName = row.firstName || '';
  const lastName = row.lastName || '';
  const leadName = [firstName, lastName].filter(Boolean).join(' ') || 'Unknown';

  // Determine call type
  const typeField = (row['inbound/outbound'] || 'outbound').toLowerCase();
  const callType = typeField === 'inbound' ? 'inbound' : 'outbound';

  // Parse priority
  let priority = 'medium';
  if (row.priority) {
    priority = row.priority.toLowerCase();
  }

  // Get queued time
  const queuedAt = row.scheduled_call_time || row.execution_time || row.created_at || new Date().toISOString();

  // Build workflow/source name
  const source = row.source || '';
  const campaignType = row.campaign_type || '';
  const workflowName = [source, campaignType].filter(Boolean).join(', ') || null;

  return {
    json: {
      id: row.queue_id,
      phone: row.phone_e164,
      leadName: leadName,
      type: callType,
      queuedAt: queuedAt,
      estimatedCallTime: row.scheduled_call_time || null,
      priority: priority,
      workflowName: workflowName,
      // Additional fields for reference
      status: row.status,
      email: row.email || null,
      contactId: row.contact_id || null,
      opportunityId: row.opportunity_id || null,
      attempts: parseInt(row.attempts) || 0,
      vapiCallId: row.vapi_call_id || null,
      callOutcome: row.call_outcome || null,
      batchPosition: parseInt(row.batch_position) || null
    }
  };
});

// Sort by priority (high > medium > low) then by queued time
const priorityOrder = { high: 0, medium: 1, low: 2 };

formattedCalls.sort((a, b) => {
  const priorityA = priorityOrder[a.json.priority] || 1;
  const priorityB = priorityOrder[b.json.priority] || 1;

  if (priorityA !== priorityB) {
    return priorityA - priorityB;
  }

  return new Date(a.json.queuedAt).getTime() - new Date(b.json.queuedAt).getTime();
});

return formattedCalls;
